'use client';
import React, { useEffect, useState, useCallback } from 'react';
import { Search, RefreshCw, AlertCircle } from 'lucide-react';
import ReportedContent from './ReportedContent';
import { API_URL } from '../api/apiURL';

const ReportDashboard = () => {
  const [reports, setReports] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [genderFilter, setGenderFilter] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [refreshKey, setRefreshKey] = useState(0);
  const itemsPerPage = 10;

  // ✅ Fetch reports with proper error handling
  const fetchReports = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      console.log('📡 Fetching reports...', {
        searchTerm,
        statusFilter,
        genderFilter,
        currentPage,
        refreshKey
      });
      
      const res = await fetch(
        `${API_URL}/admin/report-analize?search=${searchTerm}&status=${statusFilter}&gender=${genderFilter}&page=${currentPage}&limit=${itemsPerPage}&t=${Date.now()}`
      );

      if (!res.ok) {
        throw new Error(`API Error: ${res.status}`);
      }

      const data = await res.json();
      console.log('✅ Data received:', data);

      setReports(data.reports || []);
      setTotalPages(data.totalPages || 1);

    } catch (err) {
      console.error('❌ Failed to fetch reports:', err);
      setError(err.message);
      setReports([]);
    } finally {
      setLoading(false);
    }
  }, [searchTerm, statusFilter, genderFilter, currentPage, itemsPerPage, refreshKey]);

  // ✅ Manual refresh function
  const handleManualRefresh = () => {
    console.log('🔄 Manual refresh triggered');
    setRefreshKey(prev => prev + 1);
    setCurrentPage(1);
  };

  // ✅ Trigger fetch on dependencies change
  useEffect(() => {
    fetchReports();
  }, [fetchReports]);

  // ✅ Top cards calculations
  const totalReports = reports.length;
  const pendingReports = reports.filter(r => r.status?.toLowerCase() === 'pending').length;
  const reviewedReports = reports.filter(r => 
    r.status?.toLowerCase() === 'reviewed' || 
    r.status?.toLowerCase() === 'approved'
  ).length;
  const blockedReports = reports.filter(r => r.status?.toLowerCase() === 'blocked').length;

  const formatK = (num) => num >= 1000 ? (num / 1000).toFixed(1) + 'K' : num;

  return (
    <div className="p-3 sm:p-4 md:p-5 lg:p-6">
      {/* Header with Refresh Button */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">Report Dashboard</h1>
          <p className="text-gray-600 mt-1">Manage and review user reports</p>
        </div>
        
        <button
          onClick={handleManualRefresh}
          disabled={loading}
          className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition disabled:opacity-50 disabled:cursor-not-allowed min-w-[140px]"
        >
          <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
          {loading ? 'Refreshing...' : 'Refresh Data'}
        </button>
      </div>

      {/* Error Display */}
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
          <AlertCircle className="text-red-500 mt-0.5 flex-shrink-0" />
          <div>
            <p className="text-red-700 font-medium">Error loading data</p>
            <p className="text-red-600 text-sm">{error}</p>
            <button 
              onClick={handleManualRefresh}
              className="mt-2 text-sm text-red-600 hover:text-red-800 underline"
            >
              Try again
            </button>
          </div>
        </div>
      )}

      {/* ⭐ TOP CARDS — AUTO FROM TABLE DATA ⭐ */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-5 md:gap-6 px-2 sm:px-4 md:px-6 lg:px-10 mb-8 sm:mb-10">
        {[
          { 
            label: 'Total Reports', 
            value: totalReports,
            bgColor: 'bg-blue-50',
            borderColor: 'border-blue-200'
          },
          { 
            label: 'Pending Review', 
            value: pendingReports,
            bgColor: 'bg-yellow-50',
            borderColor: 'border-yellow-200'
          },
          { 
            label: 'Action Taken', 
            value: reviewedReports,
            bgColor: 'bg-green-50',
            borderColor: 'border-green-200'
          },
          { 
            label: 'Blocked Users', 
            value: blockedReports,
            bgColor: 'bg-red-50',
            borderColor: 'border-red-200'
          },
        ].map(({ label, value, bgColor, borderColor }) => (
          <div
            key={label}
            className={`${bgColor} border ${borderColor} rounded-xl shadow-sm p-4 sm:p-5 md:p-6 flex flex-col justify-center items-center transition-all hover:shadow-md`}
            style={{ minHeight: "140px" }}
          >
            <p className="text-sm sm:text-base md:text-lg font-semibold text-gray-800 text-center px-2">{label}</p>
            <p className="text-2xl sm:text-3xl md:text-4xl font-bold text-gray-900 mt-3 sm:mt-4">{formatK(value)}</p>
            <p className="text-xs text-gray-500 mt-2">Updated just now</p>
          </div>
        ))}
      </div>

      {/* SEARCH + FILTER + TABLE CONTAINER */}
      <div className="border mt-5 p-3 sm:p-4 bg-white border-gray-400 rounded-lg sm:rounded-xl shadow-sm">
        
        {/* SEARCH AND FILTERS SECTION */}
        <div className="bg-gray-50 p-3 sm:p-4 rounded-lg shadow-sm border border-gray-300 mb-4 sm:mb-5">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 sm:gap-5">
            
            {/* SEARCH BAR */}
            <div className="relative w-full lg:max-w-md">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="Search by name, email or report ID"
                value={searchTerm}
                onChange={(e) => {
                  setCurrentPage(1);
                  setSearchTerm(e.target.value);
                }}
                className="w-full pl-10 pr-4 py-2.5 bg-white border border-gray-400 rounded-lg focus:ring-2 focus:ring-blue-300 focus:border-blue-400 text-sm sm:text-base transition"
              />
            </div>

            {/* FILTERS */}
            <div className="flex flex-wrap gap-3">
              <select
                value={statusFilter}
                onChange={(e) => {
                  setCurrentPage(1);
                  setStatusFilter(e.target.value);
                }}
                className="px-4 py-2.5 border bg-white border-gray-400 rounded-lg text-sm sm:text-base min-w-[140px] focus:ring-2 focus:ring-blue-300"
              >
                <option value="all">All Status</option>
                <option value="pending">Pending</option>
                <option value="reviewed">Reviewed</option>
                <option value="approved">Approved</option>
                <option value="blocked">Blocked</option>
              </select>

              <select
                value={genderFilter}
                onChange={(e) => {
                  setCurrentPage(1);
                  setGenderFilter(e.target.value);
                }}
                className="px-4 py-2.5 border bg-white border-gray-400 rounded-lg text-sm sm:text-base min-w-[140px] focus:ring-2 focus:ring-blue-300"
              >
                <option value="">All Gender</option>
                <option value="Male">Male</option>
                <option value="Female">Female</option>
                <option value="Other">Other</option>
              </select>

              {/* Clear Filters */}
              {(searchTerm || statusFilter !== 'all' || genderFilter) && (
                <button
                  onClick={() => {
                    setSearchTerm('');
                    setStatusFilter('all');
                    setGenderFilter('');
                    setCurrentPage(1);
                  }}
                  className="px-4 py-2.5 border border-gray-400 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 text-sm sm:text-base"
                >
                  Clear Filters
                </button>
              )}
            </div>
          </div>
        </div>

        {/* LOADING STATE */}
        {loading ? (
          <div className="flex justify-center items-center py-20">
            <div className="text-center">
              <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent"></div>
              <p className="mt-4 text-gray-600">Loading reports...</p>
            </div>
          </div>
        ) : (
          <ReportedContent
            report={reports}
            currentPage={currentPage}
            totalPages={totalPages}
            setCurrentPage={setCurrentPage}
            itemsPerPage={itemsPerPage}
            refreshReports={fetchReports} // ✅ Pass refresh function
            onDataUpdate={() => setRefreshKey(prev => prev + 1)} // ✅ Trigger refresh
            loading={loading}
          />
        )}

        {/* EMPTY STATE */}
        {!loading && reports.length === 0 && (
          <div className="text-center py-12">
            <div className="inline-block p-4 bg-gray-100 rounded-full mb-4">
              <Search className="w-12 h-12 text-gray-400" />
            </div>
            <h3 className="text-xl font-semibold text-gray-700 mb-2">No reports found</h3>
            <p className="text-gray-500 mb-6">
              {searchTerm || statusFilter !== 'all' || genderFilter 
                ? 'Try changing your filters or search term'
                : 'No reports have been submitted yet'
              }
            </p>
            {(searchTerm || statusFilter !== 'all' || genderFilter) && (
              <button
                onClick={() => {
                  setSearchTerm('');
                  setStatusFilter('all');
                  setGenderFilter('');
                }}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                Clear All Filters
              </button>
            )}
          </div>
        )}

      </div>

      {/* DEBUG INFO (Remove in production) */}
      {process.env.NODE_ENV === 'development' && (
        <div className="mt-8 p-4 bg-gray-900 text-gray-100 rounded-lg text-sm font-mono">
          <div className="flex items-center gap-2 mb-2">
            <span className="text-green-400">⚡</span>
            <span>Debug Info</span>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>Reports Count: <span className="text-yellow-300">{reports.length}</span></div>
            <div>Page: <span className="text-yellow-300">{currentPage}/{totalPages}</span></div>
            <div>Refresh Key: <span className="text-yellow-300">{refreshKey}</span></div>
            <div>Status Filter: <span className="text-yellow-300">{statusFilter}</span></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReportDashboard;